'file', {
      storage: diskStorage({
        destination: (_req, _file, cb) => { if (!existsSync(DOC_ROOT)) mkdirSync(DOC_ROOT, { recursive: true }); cb(null, DOC_ROOT); },
        filename: (_req, file, cb) => cb(null, `${randomUUID()}${extensionDeAdjunto(file, EXT_DOCUMENTO) ?? '.bin'}`),
      }),
      limits: { fileSize: 25 * 1024 * 1024 },
      // No tenía NINGÚN filtro: aceptaba cualquier extensión. Se sirve siempre como
      // descarga (`res.download`), así que no era ejecutable en el navegador, pero
      // no hay razón para dejar que el repositorio documental acepte binarios.
      fileFilter: (_req, file, cb) => {
        const ok = extensionDeAdjunto(file, EXT_DOCUMENTO) !== null;
        cb(ok ? null : new BadRequestException('Tipo de archivo no permitido'), ok);
      },
    }

'file', {
    storage: memoryStorage(),
    limits: { fileSize: 10 * 1024 * 1024 },
    fileFilter: (_req, file, cb) => cb(null, /spreadsheet|excel|\.xlsx$/.test(file.mimetype) || file.originalname.toLowerCase().endsWith('.xlsx')),
  }

'file', {
      storage: diskStorage({
        destination: (req, _file, cb) => {
          const dir = join(UPLOAD_ROOT, (req.params as { id: string }).id);
          mkdirSync(dir, { recursive: true });
          cb(null, dir);
        },
        filename: (_req, file, cb) => cb(null, `${randomUUID()}${extensionDeAdjunto(file, ALLOWED_EXT) ?? '.bin'}`),
      }),
      limits: { fileSize: MAX_FILE_BYTES },
      // Se valida con `extensionDeAdjunto`, no con `extname(originalname)` a secas:
      // desde la galería del móvil el nombre puede llegar sin extensión y la foto
      // se rechazaba. La lista blanca es la misma; sólo cambia de dónde se deduce.
      fileFilter: (_req, file, cb) => {
        const ok = extensionDeAdjunto(file, ALLOWED_EXT) !== null;
        cb(ok ? null : new BadRequestException('Tipo de archivo no permitido'), ok);
      },
    }

